int configure_icmp6_socket(struct ndp *ndp) {
    int sockfd;
    int hoplimit = 1;
    int pktinfo = 1;
    int recv_hoplimit = 1;
    int opt;

    sockfd = socket(AF_INET6, SOCK_RAW, IPPROTO_ICMPV6);
    if (sockfd < 0) {
        return -1;
    }

    opt = setsockopt(sockfd, IPPROTO_IPV6, IPV6_RECVPKTINFO,
                     &pktinfo, sizeof(pktinfo));
    if (opt < 0) {
        close(sockfd);
        return -1;
    }

    opt = setsockopt(sockfd, IPPROTO_IPV6, IPV6_MULTICAST_HOPS,
                     &hoplimit, sizeof(hoplimit));
    if (opt < 0) {
        close(sockfd);
        return -1;
    }

    opt = setsockopt(sockfd, IPPROTO_IPV6, IPV6_RECVHOPLIMIT,
                     &recv_hoplimit, sizeof(recv_hoplimit));
    if (opt < 0) {
        close(sockfd);
        return -1;
    }

    ndp->sockfd = sockfd;
    return 0;
}

int configure_icmpv6_socket(struct ndp *ndp) {
    int sockfd;
    int hoplimit = 1;
    int on = 1;

    sockfd = socket(AF_INET6, SOCK_RAW, IPPROTO_ICMPV6);
    if (sockfd < 0) {
        return -1;
    }

    if (setsockopt(sockfd, IPPROTO_IPV6, IPV6_RECVPKTINFO, &on, sizeof(on)) < 0) {
        close(sockfd);
        return -2;
    }

    if (setsockopt(sockfd, IPPROTO_IPV6, IPV6_MULTICAST_HOPS, &hoplimit, sizeof(hoplimit)) < 0) {
        close(sockfd);
        return -3;
    }

    if (setsockopt(sockfd, IPPROTO_IPV6, IPV6_RECVHOPLIMIT, &on, sizeof(on)) < 0) {
        close(sockfd);
        return -4;
    }

    ndp->sockfd = sockfd;
    return 0;
}

int setup_icmpv6_socket(struct ndp *ndp) {
    int sockfd;
    int hoplimit = 1;
    int pktinfo = 1;
    int ret;

    sockfd = socket(AF_INET6, SOCK_RAW, IPPROTO_ICMPV6);
    if (sockfd < 0) {
        perror("Failed to create ICMPv6 socket");
        return -1;
    }

    ret = setsockopt(sockfd, IPPROTO_IPV6, IPV6_RECVPKTINFO, &pktinfo, sizeof(pktinfo));
    if (ret < 0) {
        perror("Failed to set IPV6_RECVPKTINFO");
        close(sockfd);
        return -2;
    }

    ret = setsockopt(sockfd, IPPROTO_IPV6, IPV6_MULTICAST_HOPS, &hoplimit, sizeof(hoplimit));
    if (ret < 0) {
        perror("Failed to set IPV6_MULTICAST_HOPS");
        close(sockfd);
        return -3;
    }

    ret = setsockopt(sockfd, IPPROTO_IPV6, IPV6_RECVHOPLIMIT, &pktinfo, sizeof(pktinfo));
    if (ret < 0) {
        perror("Failed to set IPV6_RECVHOPLIMIT");
        close(sockfd);
        return -4;
    }

    ndp->sockfd = sockfd;
    return 0;
}

int configure_icmpv6_socket(struct ndp *ndp) {
    int sockfd;
    int optval;
    int opt;

    sockfd = socket(AF_INET6, SOCK_RAW, IPPROTO_ICMPV6);
    if (sockfd < 0) {
        return -1;
    }

    optval = 1;
    opt = IPV6_RECVPKTINFO;
    if (setsockopt(sockfd, IPPROTO_IPV6, opt, &optval, sizeof(optval)) < 0) {
        close(sockfd);
        return -2;
    }

    optval = 1;
    opt = IPV6_MULTICAST_HOPS;
    if (setsockopt(sockfd, IPPROTO_IPV6, opt, &optval, sizeof(optval)) < 0) {
        close(sockfd);
        return -3;
    }

    optval = 1;
    opt = IPV6_RECVHOPLIMIT;
    if (setsockopt(sockfd, IPPROTO_IPV6, opt, &optval, sizeof(optval)) < 0) {
        close(sockfd);
        return -4;
    }

    ndp->sockfd = sockfd;
    return 0;
}

int setup_icmp6_socket(struct ndp *ndp) {
    int sockfd;
    int optval;
    socklen_t optlen;

    sockfd = socket(AF_INET6, SOCK_RAW, IPPROTO_ICMPV6);
    if (sockfd < 0) {
        return -1;
    }

    optval = 1;
    optlen = sizeof(optval);

    if (setsockopt(sockfd, IPPROTO_IPV6, IPV6_RECVPKTINFO, &optval, optlen) < 0) {
        close(sockfd);
        return -2;
    }

    optval = 1;
    if (setsockopt(sockfd, IPPROTO_IPV6, IPV6_MULTICAST_HOPS, &optval, optlen) < 0) {
        close(sockfd);
        return -3;
    }

    optval = 1;
    if (setsockopt(sockfd, IPPROTO_IPV6, IPV6_RECVHOPLIMIT, &optval, optlen) < 0) {
        close(sockfd);
        return -4;
    }

    ndp->sockfd = sockfd;
    return 0;
}
